        return False
    if s.startswith(":"):
        s = s[1:]
    return s in {"q", "quit", "quit!", "exit"}


def draw_curses(stdscr, screen: Screen, message: str = "") -> None:
    stdscr.erase()
    height, width = stdscr.getmaxyx()
    if height <= 0 or width <= 0:
        return
    normal = curses.A_NORMAL
    bold = curses.A_BOLD
    try:
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_WHITE, curses.COLOR_BLUE)
        curses.init_pair(2, curses.COLOR_WHITE, curses.COLOR_GREEN)
        curses.init_pair(3, curses.COLOR_CYAN, -1)
        status_attr = curses.color_pair(1) | curses.A_BOLD
        selected_attr = curses.color_pair(2) | curses.A_BOLD
        header_attr = curses.color_pair(3)
    except Exception:
        status_attr = curses.A_REVERSE
        selected_attr = curses.A_REVERSE
        header_attr = curses.A_BOLD

    max_body = max(0, height - 2)
    for idx, line in enumerate(screen.lines[:max_body]):
        attr = normal
        if idx == 0:
            attr = selected_attr if screen.view in {"main", "status", "help"} else bold
        elif line.endswith(":") or line in {"View switching", "View manipulation"}:
            attr = header_attr
        safe = line.replace("\t", "    ")[: max(0, width - 1)]
        try:
            stdscr.addstr(idx, 0, safe, attr)
        except curses.error:
            pass

    status = screen.status
    try:
        stdscr.addstr(max(0, height - 2), 0, status[: max(0, width - 1)].ljust(max(0, width - 1)), status_attr)
    except curses.error:
        pass
    msg = message or screen.message
    if msg:
        try:
            stdscr.addstr(max(0, height - 1), 0, msg[: max(0, width - 1)], curses.color_pair(3) if curses.has_colors() else normal)
        except curses.error:
            pass
    stdscr.refresh()


