                try:
                    current = make_screen(mapping[ch], base_rest, pager_text)
                    previous = None
                    message = ""
                except TigError as e:
                    message = e.message.strip().splitlines()[0] if e.message else ""
                draw_curses(stdscr, current, message)
                continue
            if ch == ord(":"):
                # Minimal prompt: collect until enter, recognize :q.
                curses.echo()
                height, width = stdscr.getmaxyx()
                try:
                    stdscr.addstr(height - 1, 0, ":".ljust(max(1, width - 1)))
                    stdscr.move(height - 1, 1)
                except curses.error:
                    pass
                try:
                    bs = stdscr.getstr(height - 1, 1, max(1, width - 2))
                except Exception:
                    bs = b""
                curses.noecho()
                cmd = bs.decode("utf-8", "replace")
                if command_wants_quit(cmd):
                    return 0
                message = "Unknown command"
                draw_curses(stdscr, current, message)
                continue
            message = "Unknown key, press h for help"
            draw_curses(stdscr, current, message)

    try:
        return curses.wrapper(_run)
    except curses.error as e:
        # Keep ncurses-style setupterm failures terse.
        term = os.environ.get("TERM") or "unknown"
        emit(f"Error opening terminal: {term}.\r\n")
        return 1


def key_loop_nodisplay(commands: Optional[List[str]]) -> int:
    if commands:
        return 0
    # Wait for a quit key.  This mode is intentionally quiet.
    try:
        while True:
            r, _, _ = select.select([sys.stdin], [], [], None)
            if r:
                ch = sys.stdin.read(1)
                if ch in ("q", "\x1b", ""):
                    return 0
    except Exception:
        return 0


def run_tui(view: str, rest: Sequence[str], pager_text: str) -> int:
    validate_for_view(view, rest)
    commands, script_error = script_commands()
    if script_error:
        # The original initializes the terminal then leaves alternate screen with
        # this message; printing it plainly preserves the user-visible text.
        raise TigError(script_error)
    screen = make_screen(view, rest, pager_text)
    if "TIG_NO_DISPLAY" in os.environ:
        return key_loop_nodisplay(commands)
    return key_loop_curses(screen, view, rest, pager_text, commands)


def maybe_read_pager_input() -> str:
    # Only consume stdin for pager mode when it is definitely not the keyboard.
    if sys.stdin.isatty():
        return ""
    try:
        return sys.stdin.read()
    except Exception:
        return ""


def main(argv: List[str]) -> int:
    remaining, early = parse_startup(argv)
    if early is not None:
        return early

    term_error = ensure_terminal()
    if term_error is not None:
        return term_error

    pager_text = ""
    # If stdin is piped while a controlling tty exists, preserve the input as a
    # pager buffer.  (In the benchmark's non-tty shell this path is not reached.)
    if not sys.stdin.isatty():
        pager_text = maybe_read_pager_input()
        if pager_text and not remaining:
            remaining = ["pager"]

    view, rest = normalize_args(remaining)
    try:
        return run_tui(view, rest, pager_text)
    except TigError as e:
        if e.with_help:
            emit(e.message)
        else:
            emit(e.message)
        return e.code


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
