#!/usr/bin/env python3
"""
A small, original reimplementation of the observed executable's user-facing
behavior.  It implements the documented tig command line surface and a compact
terminal UI backed by the local git command.
"""
from __future__ import annotations

import curses
import datetime as _dt
import os
import re
import select
import shlex
import subprocess
import sys
import time
from dataclasses import dataclass
from typing import List, Optional, Sequence, Tuple

VERSION = "2.6.0-g87c9c25"
NCURSES_VERSION = "6.3.20211021"

HELP_TEXT = f"""tig {VERSION} 

Usage: tig        [options] [revs] [--] [paths]
   or: tig log    [options] [revs] [--] [paths]
   or: tig show   [options] [revs] [--] [paths]
   or: tig reflog [options] [revs]
   or: tig blame  [options] [rev] [--] path
   or: tig grep   [options] [pattern]
   or: tig refs   [options]
   or: tig stash  [options]
   or: tig status
   or: tig <      [git command output]

Options:
  +<number>       Select line <number> in the first view
  -v, --version   Show version and exit
  -h, --help      Show help message and exit
  -C <path>       Start in <path>
"""

VERSION_TEXT = f"tig version {VERSION}\nncursesw version {NCURSES_VERSION}\n"

RECOGNIZED_VIEWS = {"log", "show", "reflog", "refs", "stash", "status", "blame", "grep"}


@dataclass
class Screen:
    view: str
    lines: List[str]
    status: str
    message: str = ""


class TigError(Exception):
    def __init__(self, message: str, code: int = 1, with_help: bool = False):
        super().__init__(message)
        self.message = message
        self.code = code
        self.with_help = with_help


def emit(text: str, stream=None) -> None:
    if stream is None:
        stream = sys.stdout
    stream.write(text)
    stream.flush()


def emit_error(text: str) -> None:
    # With a pseudo-terminal stdout/stderr are merged by the terminal driver;
    # in non-interactive runs the original writes these early errors to stderr.
    emit(text, sys.stderr)


def git(args: Sequence[str], check: bool = False, input_text: Optional[str] = None) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["git", *args],
        input=input_text,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
        check=check,
    )


def git_out(args: Sequence[str]) -> str:
    cp = git(args)
    return cp.stdout if cp.returncode == 0 else ""


def in_git_repo() -> bool:
    cp = git(["rev-parse", "--git-dir"])
    return cp.returncode == 0


def has_commits() -> bool:
    cp = git(["rev-parse", "--verify", "HEAD"])
    return cp.returncode == 0


def first_token_before_separator(args: Sequence[str]) -> Optional[str]:
    for arg in args:
        if arg == "--":
            return None
        if arg.startswith("+") and arg[1:].isdigit():
            continue
        if arg.startswith("-"):
            # Options are for git; they are not revision tokens here.
            continue
        return arg
    return None


def path_args_after_separator(args: Sequence[str]) -> List[str]:
    if "--" in args:
        idx = list(args).index("--")
        return list(args[idx + 1 :])
    return []


def looks_like_rev_or_path_ok(args: Sequence[str]) -> bool:
    """Best-effort check for main-view arguments.

    The real program performs a mixture of git option/revision/path parsing.  We
    reproduce the most visible behavior: an unknown non-option argument exits
    with "No revisions match..." before any repository error.
    """
    if not args:
        return True
    if args and args[0] in RECOGNIZED_VIEWS:
        return True
    if args and args[0] == "--":
        # A path after -- is accepted only if it exists.  Otherwise git reports
        # no matching revisions for the observed simple cases.
        paths = path_args_after_separator(args)
        return any(os.path.exists(p) for p in paths) if paths else False
    tok = first_token_before_separator(args)
    if tok is None:
        return True
    if os.path.exists(tok):
        return True
    # In a repository, ask git if the token names a commit-ish object.  Outside
    # a repository this command fails, matching the observed "No revisions" for
    # arbitrary tokens.
    cp = git(["rev-parse", "--verify", f"{tok}^{{commit}}"])
    return cp.returncode == 0


def parse_startup(args: List[str]) -> Tuple[List[str], Optional[int]]:
    """Handle leading -C options and help/version exits.

    The observed executable processes only a leading run of separate "-C PATH"
    options before global help/version scanning.  Combined forms such as
    -C/tmp are left for git option handling.
    """
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-h", "--help"):
            emit(HELP_TEXT)
            return args[i + 1 :], 0
        if a in ("-v", "--version"):
            emit(VERSION_TEXT)
            return args[i + 1 :], 0
        if a == "-C" and i + 1 < len(args):
            path = args[i + 1]
            try:
                os.chdir(path)
            except OSError:
                emit_error(f"tig: Failed to change directory to {path}\n")
                return [], 1
            i += 2
            continue
        break

    scan = args[i:]
    for j, a in enumerate(scan):
        if a == "--":
            break
        if a in ("-h", "--help"):
            emit(HELP_TEXT)
            return scan[j + 1 :], 0
        if a in ("-v", "--version"):
            emit(VERSION_TEXT)
            return scan[j + 1 :], 0
    return args[i:], None


def controlling_tty_available() -> bool:
    try:
        fd = os.open("/dev/tty", os.O_RDWR | getattr(os, "O_NOCTTY", 0))
    except OSError:
        return False
    else:
        os.close(fd)
        return True


def ensure_terminal() -> Optional[int]:
    if not controlling_tty_available():
        emit_error("tig: Failed to open tty for input\n")
        return 1
    term = os.environ.get("TERM") or "unknown"
    if term == "unknown":
        # ncurses writes this diagnostic to the terminal before tig can draw.
        emit(f"Error opening terminal: {term}.\r\n")
        return 1
    return None


def normalize_args(args: Sequence[str]) -> Tuple[str, List[str]]:
    if args and args[0] in RECOGNIZED_VIEWS:
        sub = args[0]
        rest = list(args[1:])
        if sub == "show":
            return "diff", rest
        return sub, rest
    return "main", list(args)


def error_no_revisions() -> TigError:
    return TigError("tig: No revisions match the given arguments\n")


def error_not_repo() -> TigError:
    return TigError("tig: Not a git repository\n")


def validate_for_view(view: str, rest: Sequence[str]) -> None:
    # Unknown first non-option arguments are reported as revision mismatches even
    # outside a git repository.
    if view == "main" and rest and not looks_like_rev_or_path_ok(rest):
        raise error_no_revisions()

    if not in_git_repo():
        raise error_not_repo()

    if view == "main" and not rest and not has_commits():
        raise error_no_revisions()

    if view == "blame":
        if not blame_path(rest):
            raise TigError("tig: Invalid number of options to blame\n\n" + HELP_TEXT, with_help=True)

    if view == "stash":
        # The full program may show an empty transient stash view if quit very
        # quickly; once loaded it reports no revisions when the stash is empty.
        if not git_out(["stash", "list"]).strip():
            raise error_no_revisions()


def short_ref_decorations(decor: str) -> str:
    if not decor:
        return ""
    names: List[str] = []
    for part in [p.strip() for p in decor.split(",")]:
        if not part:
            continue
        part = part.replace("HEAD -> ", "")
        part = part.replace("tag: ", "")
        if part == "HEAD":
            continue
        names.append(part)
    if not names:
        return ""
    return "[" + ", ".join(names) + "]"


def dirty_summary() -> bool:
    cp = git(["status", "--porcelain", "--untracked-files=normal"])
    return bool(cp.stdout.strip()) if cp.returncode == 0 else False


def now_git_date() -> str:
    # Match the observed minute precision and numeric zone.
    return time.strftime("%Y-%m-%d %H:%M %z")


def main_lines(rest: Sequence[str]) -> Screen:
    lines: List[str] = []
    if dirty_summary():
        lines.append(f"{now_git_date()} Not Committed Yet o Untracked changes")

    pretty = "%H%x00%h%x00%ad%x00%an%x00%P%x00%s%x00%D"
    cmd = ["log", "--date=format:%Y-%m-%d %H:%M %z", f"--pretty=format:{pretty}", "--decorate=short"]
    # Forward common filters/pathspecs in a conservative way.
    if rest:
        cmd.extend(rest)
    cp = git(cmd)
    if cp.returncode == 0 and cp.stdout:
        for raw in cp.stdout.splitlines():
            parts = raw.split("\x00")
            if len(parts) < 7:
                continue
            full, short, date, author, parents, subject, decor = parts[:7]
            mark = "I" if not parents.strip() else "o"
            refs = short_ref_decorations(decor)
            auth = (author[:16]).ljust(16)
            tail = f" {refs}" if refs else ""
            lines.append(f"{date} {auth} {mark}{tail} {subject}".rstrip())

    title = "Untracked changes" if lines and "Not Committed Yet" in lines[0] else ""
    if not title and lines:
        title = lines[0].split()[-1]
    return Screen("main", lines or [""], f"[main] {title}".rstrip() + " 100%")


def log_lines(rest: Sequence[str]) -> Screen:
    if not has_commits():
        return Screen("log", [], "[log] 0%")
    fmt = "commit %H%d%nAuthor: %an <%ae>%nDate:   %ad%n%n    %s%n"
    cmd = ["log", "--stat", "--decorate=short", "--date=default", f"--pretty=format:{fmt}"]
    if rest:
        cmd.extend(rest)
    out = git_out(cmd)
    lines = out.splitlines()
    first_hash = ""
    m = re.search(r"commit ([0-9a-f]{7,40})", out)
    if m:
        first_hash = m.group(1)
    return Screen("log", lines, f"[log] {first_hash} - line 1 of {max(len(lines), 1)} 100%".strip())


def diff_lines(rest: Sequence[str]) -> Screen:
    if not has_commits():
        return Screen("diff", [], "[diff] 0%")
    cmd = ["show", "--stat", "--patch", "--date=default", "--pretty=fuller", "--no-color", "--decorate=short"]
    if rest:
        cmd.extend(rest)
    out = git_out(cmd)
    lines = out.splitlines()
    first_hash = ""
    m = re.search(r"commit ([0-9a-f]{7,40})", out)
    if m:
        first_hash = m.group(1)
    return Screen("diff", lines, f"[diff] {first_hash} - line 1 of {max(len(lines), 1)} 100%".strip())


def reflog_lines(rest: Sequence[str]) -> Screen:
    out = git_out(["reflog", "--date=short", "--pretty=%h %gd %gs"])
    lines = out.splitlines()
    first = lines[0].split()[1] if lines and len(lines[0].split()) > 1 else ""
    return Screen("reflog", lines, f"[reflog] {first} - reference 1 of {max(len(lines), 1)} 100%".strip() if lines else "[reflog] 0%")


def refs_lines(rest: Sequence[str]) -> Screen:
    refs_args = ["for-each-ref", "--sort=refname", "--format=%(refname:short)%00%(objectname:short)%00%(subject)"]
    # Basic filtering flags documented for refs.
    wants = []
    if "--branches" in rest:
        wants.append("refs/heads")
    if "--remotes" in rest:
        wants.append("refs/remotes")
    if "--tags" in rest:
        wants.append("refs/tags")
    refs_args.extend(wants or ["refs/heads", "refs/remotes", "refs/tags"])
    out = git_out(refs_args)
    lines = ["  All references "]
    for raw in out.splitlines():
        name, _, subj = raw.partition("\x00")
        obj = ""
        if _:
            obj, _, subj = subj.partition("\x00")
        if name:
            lines.append(f"  {name:<14} {subj}".rstrip())
    return Screen("refs", lines, "[refs] All references 100%")


def parse_status() -> Tuple[str, List[str], List[str], List[str]]:
    cp = git(["status", "--porcelain=v1", "-b", "--untracked-files=normal"])
    branch = "On branch master"
    staged: List[str] = []
    unstaged: List[str] = []
    untracked: List[str] = []
    for line in cp.stdout.splitlines():
        if line.startswith("## "):
            info = line[3:]
            if info.startswith("No commits yet on "):
                branch = "Initial commit"
            else:
                branch_name = info.split("...")[0]
                branch = f"On branch {branch_name}"
            continue
        if len(line) < 4:
            continue
        x, y = line[0], line[1]
        path = line[3:]
        if x == "?" and y == "?":
            untracked.append(f"? {path}")
        else:
            if x != " ":
                staged.append(f"{x} {path}")
            if y != " ":
                unstaged.append(f"{y} {path}")
    return branch, staged, unstaged, untracked


def status_lines(rest: Sequence[str]) -> Screen:
    branch, staged, unstaged, untracked = parse_status()
    lines: List[str] = [branch]
    lines.append("Changes to be committed:")
    lines.extend(["  " + x for x in staged] or ["  (no files)"])
    lines.append("Changes not staged for commit:")
    lines.extend(["  " + x for x in unstaged] or ["  (no files)"])
    lines.append("Untracked files:")
    lines.extend(["  " + x for x in untracked] or ["  (no files)"])
    return Screen("status", lines, "[status] Nothing to update 100%")


def blame_path(rest: Sequence[str]) -> Optional[str]:
    if not rest:
        return None
    if "--" in rest:
        after = list(rest)[list(rest).index("--") + 1 :]
        return after[-1] if after else None
    # The path is the last non-option argument.  This covers `tig blame REV -- p`
    # and the common `tig blame p` case; git will validate it.
    candidates = [a for a in rest if not a.startswith("-")]
    return candidates[-1] if candidates else None


def blame_lines(rest: Sequence[str]) -> Screen:
    path = blame_path(rest)
    if not path:
        raise TigError("tig: Invalid number of options to blame\n\n" + HELP_TEXT, with_help=True)
    cmd = ["blame", "--date=format:%Y-%m-%d %H:%M %z", "--abbrev=7", "--", path]
    out = git_out(cmd)
    lines: List[str] = []
    for line in out.splitlines():
        # Native git blame is close enough and contains all important fields.
        line = line.replace("(", "").replace(")", "")
        lines.append(line)
    first_commit = ""
    if lines:
        first_commit = lines[0].split()[0].lstrip("^")
    return Screen("blame", lines, f"[blame] {first_commit}:{path} - line 1 of {max(len(lines), 1)} 100%")


def grep_pattern(rest: Sequence[str]) -> Optional[str]:
    args = [a for a in rest if a != "--"]
    # Skip common git-grep flags with arguments conservatively.
    skip_next = False
    candidates: List[str] = []
    for a in args:
        if skip_next:
            skip_next = False
            continue
        if a in ("-e", "-f", "--and", "--or", "--not"):
            skip_next = a in ("-e", "-f")
            continue
        if a.startswith("-"):
            continue
        candidates.append(a)
    return candidates[0] if candidates else None


def grep_lines(rest: Sequence[str]) -> Screen:
    pat = grep_pattern(rest)
    if not pat:
        return Screen("grep", [], "[grep] 0%", "No matches found")
    cp = git(["grep", "-n", "--no-color", pat])
    if cp.returncode != 0 or not cp.stdout:
        return Screen("grep", [], "[grep] 0%", "No matches found")
    lines: List[str] = []
    last_file = None
    for raw in cp.stdout.splitlines():
        file, sep, restline = raw.partition(":")
        if not sep:
            lines.append(raw)
            continue
        num, sep2, text = restline.partition(":")
        if file != last_file:
            lines.append(f"{file} ")
            last_file = file
        lines.append(f"  {num}│ {text}")
    title = last_file or ""
    return Screen("grep", lines, f"[grep] {title} - line 1 of {max(1, len(lines))} 100%")


def stash_lines(rest: Sequence[str]) -> Screen:
    out = git_out(["stash", "list"])
    lines = out.splitlines()
    if not lines:
        raise error_no_revisions()
    return Screen("stash", lines, f"[stash] stash@{{0}} - stash 1 of {len(lines)} 100%")


def pager_lines(text: str) -> Screen:
    lines = text.splitlines()
    return Screen("pager", lines, f"[pager] line 1 of {max(len(lines), 1)} 100%")


def help_screen() -> Screen:
    lines = [
        "Quick reference for tig keybindings:",
        "[-] Collapse all sections",
        "",
        "[-] generic bindings",
        "View switching",
        "   m  view-main        Show main view",
        "   d  view-diff        Show diff view",
        "   l  view-log         Show log view",
        "   L  view-reflog      Show reflog view",
        "   t  view-tree        Show tree view",
        "   f  view-blob        Show blob view",
        "   b  view-blame       Show blame view",
        "   r  view-refs        Show refs view",
        "s, S  view-status      Show status view",
        "   c  view-stage       Show stage view",
        "   y  view-stash       Show stash view",
        "   g  view-grep        Show grep view",
        "   p  view-pager       Show pager view",
        "   h  view-help        Show help view",
        "",
        "View manipulation",
        "<Enter> enter          Enter and open selected",
        "   <  back             Go back to the previous view",
        "   q  quit             Close view or quit",
    ]
    return Screen("help", lines, "[help] - line 1 of 114")


def make_screen(view: str, rest: Sequence[str], pager_text: str = "") -> Screen:
    if view == "main":
        return main_lines(rest)
    if view == "log":
        return log_lines(rest)
    if view == "diff":
        return diff_lines(rest)
    if view == "reflog":
        return reflog_lines(rest)
    if view == "refs":
        return refs_lines(rest)
    if view == "status":
        return status_lines(rest)
    if view == "blame":
        return blame_lines(rest)
    if view == "grep":
        return grep_lines(rest)
    if view == "stash":
        return stash_lines(rest)
    if view == "pager":
        return pager_lines(pager_text)
    return main_lines(rest)


def script_commands() -> Tuple[Optional[List[str]], Optional[str]]:
    if "TIG_SCRIPT" not in os.environ:
        return None, None
    value = os.environ.get("TIG_SCRIPT", "")
    if value == "":
        try:
            data = sys.stdin.read()
        except Exception:
            data = ""
        return data.splitlines(), None
    try:
        with open(value, "r", encoding="utf-8", errors="replace") as f:
            return f.read().splitlines(), None
    except OSError:
        return None, f"tig: Failed to open {value}\n"


def command_wants_quit(cmd: str) -> bool:
    s = cmd.strip()
    if not s:
        return False
    if s.startswith(":"):
        s = s[1:]
    return s in {"q", "quit", "quit!", "exit"}


def draw_curses(stdscr, screen: Screen, message: str = "") -> None:
    stdscr.erase()
    height, width = stdscr.getmaxyx()
    if height <= 0 or width <= 0:
        return
    normal = curses.A_NORMAL
    bold = curses.A_BOLD
    try:
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_WHITE, curses.COLOR_BLUE)
        curses.init_pair(2, curses.COLOR_WHITE, curses.COLOR_GREEN)
        curses.init_pair(3, curses.COLOR_CYAN, -1)
        status_attr = curses.color_pair(1) | curses.A_BOLD
        selected_attr = curses.color_pair(2) | curses.A_BOLD
        header_attr = curses.color_pair(3)
    except Exception:
        status_attr = curses.A_REVERSE
        selected_attr = curses.A_REVERSE
        header_attr = curses.A_BOLD

    max_body = max(0, height - 2)
    for idx, line in enumerate(screen.lines[:max_body]):
        attr = normal
        if idx == 0:
            attr = selected_attr if screen.view in {"main", "status", "help"} else bold
        elif line.endswith(":") or line in {"View switching", "View manipulation"}:
            attr = header_attr
        safe = line.replace("\t", "    ")[: max(0, width - 1)]
        try:
            stdscr.addstr(idx, 0, safe, attr)
        except curses.error:
            pass

    status = screen.status
    try:
        stdscr.addstr(max(0, height - 2), 0, status[: max(0, width - 1)].ljust(max(0, width - 1)), status_attr)
    except curses.error:
        pass
    msg = message or screen.message
    if msg:
        try:
            stdscr.addstr(max(0, height - 1), 0, msg[: max(0, width - 1)], curses.color_pair(3) if curses.has_colors() else normal)
        except curses.error:
            pass
    stdscr.refresh()


def key_loop_curses(initial: Screen, base_view: str, base_rest: Sequence[str], pager_text: str, commands: Optional[List[str]]) -> int:
    def _run(stdscr) -> int:
        try:
            curses.curs_set(0)
        except Exception:
            pass
        curses.noecho()
        curses.cbreak()
        stdscr.keypad(True)
        stdscr.timeout(-1)
        current = initial
        previous: Optional[Screen] = None
        message = ""
        draw_curses(stdscr, current, message)

        if commands:
            for cmd in commands:
                if command_wants_quit(cmd):
                    return 0
                # Support a tiny subset of prompt commands used in examples.
                if cmd.strip().startswith(":view-help") or cmd.strip() == "h":
                    previous = current
                    current = help_screen()
                    draw_curses(stdscr, current)
            draw_curses(stdscr, current)

        while True:
            ch = stdscr.getch()
            if ch in (ord("q"), 27):
                if current.view == "help" and previous is not None:
                    current, previous = previous, None
                    draw_curses(stdscr, current)
                    continue
                return 0
            if ch == ord("h"):
                previous = current
                current = help_screen()
                draw_curses(stdscr, current)
                continue
            mapping = {
                ord("m"): "main",
                ord("l"): "log",
                ord("L"): "reflog",
                ord("d"): "diff",
                ord("r"): "refs",
                ord("s"): "status",
                ord("S"): "status",
                ord("g"): "grep",
                ord("y"): "stash",
                ord("p"): "pager",
                ord("b"): "blame",
            }
            if ch in mapping:
                try:
                    current = make_screen(mapping[ch], base_rest, pager_text)
                    previous = None
                    message = ""
                except TigError as e:
                    message = e.message.strip().splitlines()[0] if e.message else ""
                draw_curses(stdscr, current, message)
                continue
            if ch == ord(":"):
                # Minimal prompt: collect until enter, recognize :q.
                curses.echo()
                height, width = stdscr.getmaxyx()
                try:
                    stdscr.addstr(height - 1, 0, ":".ljust(max(1, width - 1)))
                    stdscr.move(height - 1, 1)
                except curses.error:
                    pass
                try:
                    bs = stdscr.getstr(height - 1, 1, max(1, width - 2))
                except Exception:
                    bs = b""
                curses.noecho()
                cmd = bs.decode("utf-8", "replace")
                if command_wants_quit(cmd):
                    return 0
                message = "Unknown command"
                draw_curses(stdscr, current, message)
                continue
            message = "Unknown key, press h for help"
            draw_curses(stdscr, current, message)

    try:
        return curses.wrapper(_run)
    except curses.error as e:
        # Keep ncurses-style setupterm failures terse.
        term = os.environ.get("TERM") or "unknown"
        emit(f"Error opening terminal: {term}.\r\n")
        return 1


def key_loop_nodisplay(commands: Optional[List[str]]) -> int:
    if commands:
        return 0
    # Wait for a quit key.  This mode is intentionally quiet.
    try:
        while True:
            r, _, _ = select.select([sys.stdin], [], [], None)
            if r:
                ch = sys.stdin.read(1)
                if ch in ("q", "\x1b", ""):
                    return 0
    except Exception:
        return 0


def run_tui(view: str, rest: Sequence[str], pager_text: str) -> int:
    validate_for_view(view, rest)
    commands, script_error = script_commands()
    if script_error:
        # The original initializes the terminal then leaves alternate screen with
        # this message; printing it plainly preserves the user-visible text.
        raise TigError(script_error)
    screen = make_screen(view, rest, pager_text)
    if "TIG_NO_DISPLAY" in os.environ:
        return key_loop_nodisplay(commands)
    return key_loop_curses(screen, view, rest, pager_text, commands)


def maybe_read_pager_input() -> str:
    # Only consume stdin for pager mode when it is definitely not the keyboard.
    if sys.stdin.isatty():
        return ""
    try:
        return sys.stdin.read()
    except Exception:
        return ""


def main(argv: List[str]) -> int:
    remaining, early = parse_startup(argv)
    if early is not None:
        return early

    term_error = ensure_terminal()
    if term_error is not None:
        return term_error

    pager_text = ""
    # If stdin is piped while a controlling tty exists, preserve the input as a
    # pager buffer.  (In the benchmark's non-tty shell this path is not reached.)
    if not sys.stdin.isatty():
        pager_text = maybe_read_pager_input()
        if pager_text and not remaining:
            remaining = ["pager"]

    view, rest = normalize_args(remaining)
    try:
        return run_tui(view, rest, pager_text)
    except TigError as e:
        if e.with_help:
            emit(e.message)
        else:
            emit(e.message)
        return e.code


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
